import codecs, json, sys, unicodedata
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == '16.0.0'
points = [[], [65], [0], [0x10000], [0xd800], [0xdc00], [0xd800,0xdc00], [0xd800,0xd800,0xdc00,0xdc00], [0x10000,0xd800,0xdc00,0], [39,34,92,10,0xd800,0xdc00]]
rows = []
fault = None
def decode(data, errors='strict'):
    raise fault
codecs.register(lambda name: (None, decode, None, None) if name == 'point_fault' else None)
for name in ['ValueError', 'UnicodeError', 'LookupError', 'IndexError', 'KeyError', 'TypeError']:
    for index, scalars in enumerate(points):
        message = ''.join(chr(point) for point in scalars)
        for mode in ['exec', 'eval']:
            fault = getattr(__builtins__, name)(message)
            try:
                compile(b'# coding: point-fault\n1', 'point-fault.py', mode)
            except BaseException as error:
                expected = {'type': type(error).__name__, 'points': list(map(ord,error.args[0])), 'same': error is fault}
                if isinstance(error, SyntaxError):
                    expected.update(filename=error.filename, line=error.lineno, offset=error.offset, text=error.text, msgAlias=error.msg is error.args[0])
                rows.append(dict(name=name,index=index,points=scalars,mode=mode,expected=expected))
print(json.dumps(dict(version=sys.version,unicode=unicodedata.unidata_version,platform=sys.platform,rows=rows)))
